export function makeT(getLang) {
  const T = (key, vars = {}) => {
    const s = DICT[getLang()]?.[key] ?? DICT.nb[key] ?? key;
    return s.replace(/\{(\w+)\}/g, (_, k) => (vars[k] ?? `{${k}}`));
  };
  const name = (kind, fallback) => { const n = NAMES[kind]; return n ? n[getLang() === 'en' ? 1 : 0] : fallback; };
  return { T, name };
}
