// Slå opp uten T-fabrikken (for moduler som får språket som argument)
export const tl = (lang, key, vars = {}) => (DICT[lang]?.[key] ?? DICT.nb[key] ?? key).replace(/\{(\w+)\}/g, (_, v) => vars[v] ?? `{${v}}`);

export const DICT_KEYS = { nb: Object.keys(DICT.nb), en: Object.keys(DICT.en) };
